insert into public.profiles(id,display_name,status) values ('c9000000-0000-4000-8000-000000000001','Synthetic admin','active'),('c9000000-0000-4000-8000-000000000002','Synthetic other','active');
insert into public.platform_admins(user_id,admin_role) values ('c9000000-0000-4000-8000-000000000001','admin');
insert into public.companies(id,name) values ('c9000000-0000-4000-8000-000000000010','Onboarding own'),('c9000000-0000-4000-8000-000000000011','Onboarding foreign');
insert into public.websites(id,company_id,name,public_slug,created_by) values
 ('c9000000-0000-4000-8000-000000000020','c9000000-0000-4000-8000-000000000010','Own fixture','onboarding-own-fixture','c9000000-0000-4000-8000-000000000001'),
 ('c9000000-0000-4000-8000-000000000021','c9000000-0000-4000-8000-000000000011','Foreign fixture','onboarding-foreign-fixture','c9000000-0000-4000-8000-000000000001');
insert into public.website_drafts(website_id,content,updated_by) select id,'{"businessName":"Local onboarding fixture","accent":"#112233","accent2":"#445566","bg":"#ffffff","activePageId":"home","pages":[{"id":"home","slug":"","name":"Forside","offerings":[],"gallery":[],"sections":[]}]}','c9000000-0000-4000-8000-000000000001' from public.websites where id in ('c9000000-0000-4000-8000-000000000020','c9000000-0000-4000-8000-000000000021');
create temporary table fixture(label text primary key, invitation uuid, target uuid);
grant select on fixture to authenticated,service_role;
create function pg_temp.claims(p_user uuid,p_aal text default 'aal2',p_password boolean default true) returns void language sql as $$
 select set_config('request.jwt.claims',jsonb_build_object('sub',p_user,'role','authenticated','aal',p_aal,'amr',case when p_password then '[{"method":"password"}]'::jsonb else '[{"method":"invite"},{"method":"totp"}]'::jsonb end)::text,true)::text::void;
$$;
create function pg_temp.invite(p_label text,p_password boolean default true,p_factor boolean default true) returns void language plpgsql as $$
declare prepared jsonb; target uuid:=gen_random_uuid(); invitation uuid;
begin
 perform pg_temp.claims('c9000000-0000-4000-8000-000000000001');
 prepared:=public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010',p_label||'@test.invalid','Synthetic customer','editor');
 invitation:=(prepared->>'invitationId')::uuid;
 insert into auth.users(id,email,created_at,invited_at,email_confirmed_at,encrypted_password,raw_user_meta_data)
 values(target,p_label||'@test.invalid',now(),now(),now(),case when p_password then 'synthetic-not-a-valid-password-hash' else '' end,jsonb_build_object('wreach_invitation_id',invitation));
 if p_factor then insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),target,'totp','verified',now(),now()); end if;
 if (public.security_v2_finalize_customer_invite(invitation)->>'ok')<>'true' then raise exception 'Fixture finalization failed'; end if;
 insert into fixture values(p_label,invitation,target);
end $$;

select ok(not has_table_privilege('authenticated','private.customer_invitations','SELECT'),'invitation internals inaccessible to browser');
select ok(not has_table_privilege('service_role','private.customer_invitations','UPDATE'),'service has no direct invitation mutation grant');
select ok(not has_function_privilege('authenticated','public.security_v2_finalize_customer_invite(uuid)','EXECUTE'),'browser cannot finalize Auth binding');
select ok(not has_function_privilege('anon','public.security_v2_customer_onboarding_status()','EXECUTE'),'anonymous onboarding status denied');
select ok(not has_function_privilege('service_role','public.security_v2_accept_customer_invitation(uuid)','EXECUTE'),'activation requires user JWT, not service role');
select ok((select bool_and(proconfig @> array['search_path=""']) from pg_proc where proname in ('security_v2_prepare_customer_invite','security_v2_finalize_customer_invite','security_v2_customer_onboarding_status','security_v2_accept_customer_invitation','security_v2_revoke_customer_invitation')),'all definers secure search_path');

set local role authenticated;
select pg_temp.claims('c9000000-0000-4000-8000-000000000002');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','denied@test.invalid','Customer','editor')->>'error','NOT_AUTHORIZED','non-admin cannot invite');
select pg_temp.claims('c9000000-0000-4000-8000-000000000001','aal1');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','denied@test.invalid','Customer','editor')->>'error','NOT_AUTHORIZED','AAL1 admin cannot invite');
select pg_temp.claims('c9000000-0000-4000-8000-000000000001');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','denied@test.invalid','Customer',null)->>'error','INVALID_REQUEST','explicit role required');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','denied@test.invalid','Customer','owner')->>'error','INVALID_REQUEST','owner invitation not allowed');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','denied@test.invalid','Customer','publisher')->>'error','INVALID_REQUEST','no automatic publishing grant');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','onboarding-admin@test.invalid','Customer','editor')->>'error','EXISTING_IDENTITY_REQUIRES_REVIEW','existing admin identity not taken over');
reset role;
select pg_temp.invite('onboarding-main');
select is((select status from public.company_memberships where user_id=(select target from fixture where label='onboarding-main')),'invited','membership starts invited');
select is((select role from public.company_memberships where user_id=(select target from fixture where label='onboarding-main')),'editor','role matches explicit invitation');
select is((select company_id from public.profiles where id=(select target from fixture where label='onboarding-main')),null::uuid,'no legacy company_id bypass');
select is((select count(*) from public.platform_admins where user_id=(select target from fixture where label='onboarding-main')),0::bigint,'customer not platform admin');
select is((select count(*) from public.audit_events where event_type='customer.invite' and target_id=(select target from fixture where label='onboarding-main')),1::bigint,'invite audited exactly once');
select is(public.security_v2_finalize_customer_invite((select invitation from fixture where label='onboarding-main'))->>'status','invited','finalize replay succeeds without duplication');
select is((select count(*) from public.audit_events where event_type='customer.invite' and target_id=(select target from fixture where label='onboarding-main')),1::bigint,'no duplicate invitation audit');
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-main'),'aal1');
select is(public.security_v2_customer_onboarding_status()->>'status','invited','AAL1 sees only own onboarding state');
select ok(not (public.security_v2_customer_onboarding_status() ? 'companyId'),'AAL1 status exposes no company data');
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-main'))->>'error','AAL2_REQUIRED','AAL1 cannot activate despite verified factor');
select is((select count(*) from public.companies),0::bigint,'AAL1 tenant read denied');
select pg_temp.claims((select target from fixture where label='onboarding-main'));
select is((select count(*) from public.companies),0::bigint,'AAL2 invited has no tenant access');
select is((select count(*) from public.websites),0::bigint,'AAL2 invited cannot read websites');
select is((select count(*) from public.website_drafts),0::bigint,'AAL2 invited cannot read drafts');
select pg_temp.claims('c9000000-0000-4000-8000-000000000002');
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-main'))->>'error','INVITATION_UNAVAILABLE','wrong user cannot accept');
select is(public.security_v2_customer_onboarding_status()->>'status','none','no email-based identity matching');
select pg_temp.claims((select target from fixture where label='onboarding-main'));
select is(public.security_v2_accept_customer_invitation(gen_random_uuid())->>'error','INVITATION_UNAVAILABLE','arbitrary invitation ID denied');
select pg_temp.claims((select target from fixture where label='onboarding-main'),'aal2',false);
select is(public.security_v2_customer_onboarding_status()->>'passwordRequired','true','invite plus TOTP and generated password hash do not prove a chosen password');
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-main'))->>'error','PASSWORD_REQUIRED','AAL2 invite session without password AMR cannot activate');
select pg_temp.claims((select target from fixture where label='onboarding-main'));
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-main'))->>'status','active','own AAL2 invite accepted');
select is(public.security_v2_customer_onboarding_status()->>'status','accepted','server remembers acceptance across reload');
select is((select count(*) from public.companies),1::bigint,'own company only after activation');
select is((select count(*) from public.companies where id='c9000000-0000-4000-8000-000000000011'),0::bigint,'foreign company denied');
select is((select count(*) from public.websites),1::bigint,'only own website accessible');
select is((select count(*) from public.website_drafts),1::bigint,'only own draft accessible');
select is((select count(*) from public.audit_events),0::bigint,'internal audit denied');
select ok(not public.is_platform_admin(),'no platform-admin escalation');
select throws_ok('update public.company_memberships set role=''owner''','42501',null,'customer cannot change roles or tenant membership');
select throws_ok('insert into public.platform_admins(user_id,admin_role) values(auth.uid(),''owner'')','42501',null,'customer cannot promote itself');
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-main'))->>'status','active','activation replay idempotent');
reset role;
select is((select count(*) from public.audit_events where event_type='customer.invite_accept' and actor_user_id=(select target from fixture where label='onboarding-main')),1::bigint,'single acceptance audit');
select is((select count(*) from public.company_memberships where user_id=(select target from fixture where label='onboarding-main')),1::bigint,'single membership after replay');
update public.company_memberships set role='publisher' where user_id=(select target from fixture where label='onboarding-main');
update auth.users set email='onboarding-updated@test.invalid' where id=(select target from fixture where label='onboarding-main');
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-main'));
select is(public.security_v2_customer_onboarding_status()->>'status','accepted','completed onboarding does not undo later authorized role/email changes');
select is(public.security_v2_customer_onboarding_status()->>'passwordRequired','false','completed onboarding does not restart first-password flow');
reset role;
select pg_temp.invite('onboarding-password',false);
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-password'));
select is(public.security_v2_customer_onboarding_status()->>'passwordRequired','true','password state derived from Auth');
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-password'))->>'error','PASSWORD_REQUIRED','cannot skip first password');
