set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-factor'));
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-factor'))->>'error','NOT_AUTHORIZED','AAL2 claim without verified TOTP rejected');
