select is(public.security_v2_revoke_customer_invitation((select invitation from fixture where label='onboarding-revoked'))->>'status','revoked','admin revokes pending invitation');
select is(public.security_v2_revoke_customer_invitation((select invitation from fixture where label='onboarding-main'))->>'error','INVITATION_UNAVAILABLE','revocation cannot disable an accepted member without separate critical operation');
select pg_temp.claims((select target from fixture where label='onboarding-revoked'));
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-revoked'))->>'error','INVITATION_UNAVAILABLE','revoked invitation denied');
reset role;
select pg_temp.invite('onboarding-tampered');
update public.company_memberships set role='owner' where user_id=(select target from fixture where label='onboarding-tampered');
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-tampered'));
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-tampered'))->>'error','INVITATION_UNAVAILABLE','role binding enforced');
