select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-company'))->>'error','INVITATION_UNAVAILABLE','company binding enforced');
reset role;
select pg_temp.invite('onboarding-atomic');
create function pg_temp.reject_acceptance_audit() returns trigger language plpgsql as $$
begin
 if new.event_type='customer.invite_accept' then raise exception 'synthetic audit failure'; end if;
 return new;
end $$;
create trigger onboarding_audit_failure before insert on public.audit_events for each row execute function pg_temp.reject_acceptance_audit();
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-atomic'));
select throws_ok('select public.security_v2_accept_customer_invitation((select invitation from fixture where label=''onboarding-atomic''))','P0001','synthetic audit failure','audit failure aborts activation');
reset role;
select is((select status from public.company_memberships where user_id=(select target from fixture where label='onboarding-atomic')),'invited','audit failure rolls membership back');
select is((select status from private.customer_invitations where id=(select invitation from fixture where label='onboarding-atomic')),'invited','audit failure rolls invitation back');
drop trigger onboarding_audit_failure on public.audit_events;
update public.profiles set status='suspended' where id=(select target from fixture where label='onboarding-atomic');
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-atomic'));
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-atomic'))->>'error','NOT_AUTHORIZED','suspended profile cannot activate');
reset role;
select pg_temp.claims('c9000000-0000-4000-8000-000000000001');
create temporary table reservation as select public.security_v2_prepare_customer_invite('c9000000-0000-4000-8000-000000000090','c9000000-0000-4000-8000-000000000010','onboarding-duplicate@test.invalid','Synthetic','editor') as response;
select is((select response->>'send' from reservation),'true','first reservation sends once');
select is(public.security_v2_prepare_customer_invite('c9000000-0000-4000-8000-000000000090','c9000000-0000-4000-8000-000000000010','onboarding-duplicate@test.invalid','Synthetic','editor')->>'send','false','same attempt never resends email');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','onboarding-duplicate@test.invalid','Synthetic','editor')->>'error','INVITATION_CONFLICT','different-key duplicate invitation blocked');
select is(public.security_v2_prepare_customer_invite('c9000000-0000-4000-8000-000000000090','c9000000-0000-4000-8000-000000000011','onboarding-duplicate@test.invalid','Synthetic','editor')->>'error','INVITATION_CONFLICT','same key different company blocked');
select is(public.security_v2_finalize_customer_invite((select (response->>'invitationId')::uuid from reservation))->>'error','DELIVERY_UNCONFIRMED','failed Auth/email leaves traceable reservation, no privileged orphan');
select is((select count(*) from public.company_memberships where user_id in (select id from auth.users where email='onboarding-duplicate@test.invalid')),0::bigint,'no membership after failed delivery');
select ok(not exists(select 1 from public.audit_events where event_type like 'customer.invite%' and metadata::text ~* '(password|secret|token|authorization|qr|@test.invalid)'),'audit excludes secrets and email');

-- Normal invite cannot erase terminal history; recovery is a separate operation.
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','onboarding-revoked@test.invalid','Synthetic customer','editor')->>'error','INVITATION_CONFLICT','PILOT BLOCKER: revoke plus new request cannot reissue');
select is(public.security_v2_prepare_customer_invite((select request_id from private.customer_invitations where email='onboarding-revoked@test.invalid'),'c9000000-0000-4000-8000-000000000010','onboarding-revoked@test.invalid','Synthetic customer','editor')->>'error','INVITATION_UNAVAILABLE','PILOT BLOCKER: original revoked request cannot resend');
select is(public.security_v2_prepare_customer_invite((select request_id from private.customer_invitations where email='onboarding-expired@test.invalid'),'c9000000-0000-4000-8000-000000000010','onboarding-expired@test.invalid','Synthetic customer','editor')->>'error','INVITATION_UNAVAILABLE','PILOT BLOCKER: original expired request cannot resend');
select is(public.security_v2_prepare_customer_invite(gen_random_uuid(),'c9000000-0000-4000-8000-000000000010','onboarding-expired@test.invalid','Synthetic customer','editor')->>'error','INVITATION_CONFLICT','PILOT BLOCKER: new request cannot replace expired invitation');

-- Revised deployment contract: old direct writer is explicitly UNSUPPORTED.
-- Maintenance has no DB IO (matrix in invitation-maintenance.test.mjs). Existing
-- new-Edge real HTTP tests prove the supported writer. Never grant this bypass.
insert into auth.users(id,email) values('c9000000-0000-4000-8000-000000000099','onboarding-legacy-path@test.invalid');
set local role service_role;
select lives_ok($q$insert into public.profiles(id,email,display_name,status) values('c9000000-0000-4000-8000-000000000099','onboarding-legacy-path@test.invalid','Synthetic legacy customer','active') on conflict(id) do update set display_name=excluded.display_name,status=excluded.status$q$,'old Edge profile upsert remains permitted after additive migration');
select throws_ok($q$insert into public.company_memberships(company_id,user_id,role,status,invited_by) values('c9000000-0000-4000-8000-000000000010','c9000000-0000-4000-8000-000000000099','editor','invited','c9000000-0000-4000-8000-000000000001')$q$,'42501',null,'old Edge plus new DB remains unsupported, not a rollback target');
select lives_ok($q$insert into public.audit_events(actor_user_id,company_id,event_type,result,target_type,target_id,authorization_requirements,request_correlation_id,metadata) values('c9000000-0000-4000-8000-000000000001','c9000000-0000-4000-8000-000000000010','user.invite','success','user','c9000000-0000-4000-8000-000000000099',array['aal2','platform_admin'],gen_random_uuid(),'{"role":"editor"}')$q$,'old Edge audit insert remains permitted');
reset role;
select is((select count(*) from private.customer_invitations where user_id='c9000000-0000-4000-8000-000000000099'),0::bigint,'new invitation features inert for old writes; no trigger backfill');
set local role authenticated;
select pg_temp.claims('c9000000-0000-4000-8000-000000000099');
select is(public.security_v2_customer_onboarding_status()->>'status','none','legacy identity is not silently converted into new invitation flow');
select is((select count(*) from public.companies),0::bigint,'legacy invited membership still grants no tenant access');
reset role;
-- Recovery exercises real definers against disposable bound identities.
select pg_temp.invite('onboarding-recovery');
create temporary table recovered as select public.security_v2_prepare_invitation_recovery(
 'c9000000-0000-4000-8000-000000000080',(select invitation from fixture where label='onboarding-recovery'),
 'c9000000-0000-4000-8000-000000000010') as r;
grant select on recovered to authenticated;
select is((select r->>'ok' from recovered),'true','valid pending recovery allowed');
select is((select status from private.customer_invitations where id=(select invitation from fixture where label='onboarding-recovery')),'superseded','old pending generation preserved terminal');
select is(public.security_v2_prepare_invitation_recovery('c9000000-0000-4000-8000-000000000080',(select invitation from fixture where label='onboarding-recovery'),'c9000000-0000-4000-8000-000000000010')->>'invitationId',(select r->>'invitationId' from recovered),'recovery replay returns same generation');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select (r->>'invitationId')::uuid from recovered),'c9000000-0000-4000-8000-000000000010')->>'error','RESEND_THROTTLED','resend rate limited across generations');
select is(public.security_v2_claim_invitation_delivery((select (r->>'attemptId')::uuid from recovered))->>'send','true','durable attempt dispatches once');
select is(public.security_v2_claim_invitation_delivery((select (r->>'attemptId')::uuid from recovered))->>'send','false','replay cannot resend email');
select is(public.security_v2_finish_invitation_delivery((select (r->>'attemptId')::uuid from recovered),true)->>'ok','true','delivery receipt recorded');
select is(public.security_v2_finalize_customer_invite((select (r->>'invitationId')::uuid from recovered))->>'status','invited','new generation reconciles existing binding');
select is((select count(*) from public.company_memberships where user_id=(select target from fixture where label='onboarding-recovery')),1::bigint,'recovery never duplicates membership');
select is((select role from public.company_memberships where user_id=(select target from fixture where label='onboarding-recovery')),'editor','recovery preserves role');
select is((select count(*) from public.audit_events where event_type='customer.invite_recovery_delivery' and request_correlation_id=(select (r->>'attemptId')::uuid from recovered)),1::bigint,'recovery delivery audited once');
select public.security_v2_finish_invitation_delivery((select (r->>'attemptId')::uuid from recovered),true);
select is((select count(*) from public.audit_events where event_type='customer.invite_recovery_delivery' and request_correlation_id=(select (r->>'attemptId')::uuid from recovered)),1::bigint,'receipt replay has no duplicate audit');
set local role authenticated;
select pg_temp.claims((select target from fixture where label='onboarding-recovery'));
select is(public.security_v2_accept_customer_invitation((select invitation from fixture where label='onboarding-recovery'))->>'error','INVITATION_UNAVAILABLE','old generation cannot activate');
select is(public.security_v2_customer_onboarding_status()->>'invitationId',(select r->>'invitationId' from recovered),'customer status chooses current generation');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select (r->>'invitationId')::uuid from recovered),'c9000000-0000-4000-8000-000000000010')->>'error','NOT_AUTHORIZED','customer cannot recover own invitation');
select is(public.security_v2_list_customer_invitations('c9000000-0000-4000-8000-000000000010')->>'error','NOT_AUTHORIZED','customer cannot list invitation internals');
reset role;
select pg_temp.claims('c9000000-0000-4000-8000-000000000001','aal1');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select (r->>'invitationId')::uuid from recovered),'c9000000-0000-4000-8000-000000000010')->>'error','NOT_AUTHORIZED','AAL1 admin cannot recover');
select pg_temp.claims('c9000000-0000-4000-8000-000000000002');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select (r->>'invitationId')::uuid from recovered),'c9000000-0000-4000-8000-000000000010')->>'error','NOT_AUTHORIZED','non-admin cannot recover');
select pg_temp.claims('c9000000-0000-4000-8000-000000000001');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select (r->>'invitationId')::uuid from recovered),'c9000000-0000-4000-8000-000000000011')->>'error','INVITATION_NOT_FOUND','wrong-company context rejected');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select invitation from fixture where label='onboarding-main'),'c9000000-0000-4000-8000-000000000010')->>'error','ACTIVE_MEMBERSHIP_EXISTS','accepted/active customer cannot recover');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select invitation from fixture where label='onboarding-tampered'),'c9000000-0000-4000-8000-000000000010')->>'error','BINDING_MISMATCH','role tampering blocks recovery');
select is(public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select invitation from fixture where label='onboarding-company'),'c9000000-0000-4000-8000-000000000010')->>'error','BINDING_MISMATCH','company tampering blocks recovery');
create temporary table reissued as select 'revoked' as label,public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select invitation from fixture where label='onboarding-revoked'),'c9000000-0000-4000-8000-000000000010') as r
union all select 'expired',public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select invitation from fixture where label='onboarding-expired'),'c9000000-0000-4000-8000-000000000010');
select is((select r->>'ok' from reissued where label='revoked'),'true','explicit reissue after revoked supported');
select is((select status from private.customer_invitations where id=(select invitation from fixture where label='onboarding-revoked')),'revoked','revoked generation remains terminal');
select is((select r->>'ok' from reissued where label='expired'),'true','expired invitation gets new generation');
select is((select status from private.customer_invitations where id=(select invitation from fixture where label='onboarding-expired')),'expired','expired history remains');
select is(public.security_v2_finalize_customer_invite((select (r->>'invitationId')::uuid from reissued where label='revoked'))->>'status','invited','removed bound membership becomes only invited, never active');
select is((select count(*) from public.company_memberships where user_id=(select target from fixture where label='onboarding-revoked')),1::bigint,'reissue reuses exact membership');
select ok(not exists(select 1 from public.audit_events where event_type like 'customer.invite_recovery%' and metadata::text ~* '(password|secret|token|authorization|qr|@test.invalid)'),'recovery audit contains no secrets/email');
select ok(not has_function_privilege('authenticated','public.security_v2_claim_invitation_delivery(uuid)','EXECUTE'),'browser cannot dispatch/read bound email via service RPC');
select ok(not has_table_privilege('service_role','private.customer_invitation_deliveries','UPDATE'),'delivery journal has no direct service writes');
select ok((select bool_and(proconfig @> array['search_path=""']) from pg_proc where proname in ('customer_invitation_identity','security_v2_prepare_invitation_recovery','security_v2_claim_invitation_delivery','security_v2_finish_invitation_delivery','security_v2_list_customer_invitations','security_v2_authorize_invitation_reconcile')),'recovery definers secure search_path');
select pg_temp.claims('c9000000-0000-4000-8000-000000000001');
create temporary table uncertain_recovery as select public.security_v2_prepare_invitation_recovery(gen_random_uuid(),(select (response->>'invitationId')::uuid from reservation),'c9000000-0000-4000-8000-000000000010') as r;
select is((select r->>'ok' from uncertain_recovery),'true','unconfirmed reservation can recover without direct DB repair');
select is(public.security_v2_claim_invitation_delivery((select (r->>'attemptId')::uuid from uncertain_recovery))->>'mode','invite','absent Auth identity uses new invitation delivery');
select is(public.security_v2_finish_invitation_delivery((select (r->>'attemptId')::uuid from uncertain_recovery),false)->>'ok','true','uncertain receipt safely recorded');
select is((select state from private.customer_invitation_deliveries where id=(select (r->>'attemptId')::uuid from uncertain_recovery)),'uncertain','uncertainty durable and visible to operator');
select is(public.security_v2_claim_invitation_delivery((select (r->>'attemptId')::uuid from uncertain_recovery))->>'send','false','uncertain dispatch is never replayed automatically');
select is(public.security_v2_finalize_customer_invite((select (r->>'invitationId')::uuid from uncertain_recovery))->>'error','DELIVERY_UNCONFIRMED','reconciliation truthfully reports missing Auth identity');
select is(public.security_v2_authorize_invitation_reconcile((select (r->>'invitationId')::uuid from uncertain_recovery),'c9000000-0000-4000-8000-000000000011')->>'error','INVITATION_NOT_FOUND','reconcile cannot switch company');
select * from finish();
rollback;
